function evidence = f90_xtherm04_extract_candidate_evidence( ...
        candidatePath, outDir)
%F90_XTHERM04_EXTRACT_CANDIDATE_EVIDENCE Candidate heat-pump replay.
arguments
    candidatePath (1,1) string
    outDir (1,1) string
end
[taskRoot,sharedRoot]=localRoots("F90-XTHERM-04");
addpath(sharedRoot,"-begin");cleanup=onCleanup(@()rmpath(sharedRoot)); %#ok<NASGU>
official=jsondecode(fileread(simuverity_official_scenarios_path()));
spec=struct("schema","simuverity.f90-xtherm04-evidence.v1", ...
    "task_id","F90-XTHERM-04","scenarios",official.scenarios, ...
    "output_contract",localOutputs,"input_builder",@localInputs, ...
    "requested_input_builder",@localRequested, ...
    "stop_time",@(~,~)double(official.simulation.stop_time_s), ...
    "postprocess",@localPostprocess,"static_audit",@localAudit, ...
    "evidence_sample_s",10.0);
evidence=simuverity_run_candidate_evidence(candidatePath,outDir,spec);
end
function rows=localOutputs
rows=localRows(["thermal_state","hvac_control","heat_flow_state", ...
    "power_cop_state","refrigerant_state"],[3 4 3 5 6]);
end
function inputs=localInputs(s,~)
inputs=struct("T_house_init",double(s.T_house_init_degC), ...
    "T_set",double(s.T_set_degC),"T_ambient_cold", ...
    double(s.T_ambient_cold_degC),"T_ambient_hot", ...
    double(s.T_ambient_hot_degC),"internal_heat_gain_scale", ...
    double(s.internal_heat_gain_scale));
end
function requested=localRequested(s,~),requested=rmfield(s,"id");end
function row=localPostprocess(row,outputs,scenario,~)
row.outputs=outputs;
values=[outputs.thermal_state,outputs.hvac_control, ...
    outputs.heat_flow_state,outputs.power_cop_state,outputs.refrigerant_state];
row.metrics=struct("finite_fraction",mean(isfinite(values),"all"), ...
    "requested_T_set_degC",double(scenario.T_set_degC), ...
    "requested_T_house_init_degC",double(scenario.T_house_init_degC), ...
    "requested_T_ambient_cold_degC",double(scenario.T_ambient_cold_degC), ...
    "requested_T_ambient_hot_degC",double(scenario.T_ambient_hot_degC), ...
    "requested_internal_heat_gain_scale", ...
        double(scenario.internal_heat_gain_scale));
row.valid=row.output_contract.all_required_pass&&row.metrics.finite_fraction>=0.999999;
end
function audit=localAudit(model,spec)
structure=simuverity_candidate_structure(model,string({spec.output_contract.name})');
semantic=structure.semantic_types;
compressor=nnz(contains(semantic,"compressor"));
exchanger=nnz(contains(semantic,["heat exchanger","condenser","evaporator"]));
valve=nnz(contains(semantic,["expansion valve","orifice","restriction"]));
controller=nnz(contains(semantic,["controller","pid","stateflow"]));
thermo=structure.physical_connection_block_count>=6&&compressor>=1&& ...
    exchanger>=2&&valve>=1;
audit=struct("required_products_available",true, ...
    "thermo_fluid_path_signature",thermo, ...
    "closed_loop_temperature_signature",controller>=1&& ...
        structure.signal_cycle_present);
end
function rows=localRows(names,widths)
rows=repmat(struct("name","","evidence_name","","width",0, ...
    "interpolation","linear"),numel(names),1);
for k=1:numel(names),rows(k).name=names(k);rows(k).evidence_name=names(k); ...
    rows(k).width=widths(k);end
end
function [taskRoot,sharedRoot]=localRoots(taskId)
scriptRoot=fileparts(mfilename("fullpath"));tasksRoot=fileparts(scriptRoot);
sharedRoot=fullfile(tasksRoot,"_shared");repoRoot=tasksRoot;
for k=1:3,repoRoot=fileparts(repoRoot);end
taskRoot=string(getenv("SIMUVERITY_TASK_ROOT"));
end
